using System;
using System.IO;
using System.Linq;
using Unity.Collections;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
namespace Snowglow.Editor {
 public static class ExhaustTipCorrection {
 const string Logs="Logs/ExhaustSmoke/TipCorrection",Request="Logs/CorrectExhaustTips.request";static int checks;
 static T[] All<T>(Scene s)where T:Component=>s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<T>(true)).ToArray();
 static void Check(bool ok,string message){if(!ok)throw new InvalidOperationException("Exhaust tip: "+message);checks++;}
 [InitializeOnLoadMethod]static void Register(){EditorApplication.update+=Pending;}
 static void Pending(){if(!File.Exists(Request)){EditorApplication.update-=Pending;return;}if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;EditorApplication.update-=Pending;File.Delete(Request);try{Run();}catch(Exception e){Directory.CreateDirectory(Logs);File.WriteAllText(Logs+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
 static string Curve(ParticleSystem.MinMaxCurve c)=>c.mode+"/"+c.constantMin.ToString("R")+"/"+c.constantMax.ToString("R")+"/"+c.curveMultiplier.ToString("R")+"/"+string.Join(",",c.curveMin==null?Array.Empty<string>():c.curveMin.keys.Select(k=>k.time.ToString("R")+":"+k.value.ToString("R")))+"/"+string.Join(",",c.curveMax==null?Array.Empty<string>():c.curveMax.keys.Select(k=>k.time.ToString("R")+":"+k.value.ToString("R")));
 static string Settings(ParticleSystem p){var m=p.main;var v=p.velocityOverLifetime;var shape=p.shape;var r=p.GetComponent<ParticleSystemRenderer>();return Curve(m.startSpeed)+"|"+m.simulationSpeed.ToString("R")+"|"+Curve(v.x)+Curve(v.y)+Curve(v.z)+"|"+v.space+"|"+Curve(m.gravityModifier)+"|"+Curve(m.startLifetime)+"|"+Curve(m.startSize)+"|"+m.maxParticles+"|"+shape.radius.ToString("R")+"|"+shape.angle.ToString("R")+"|"+AssetDatabase.GetAssetPath(r.mesh)+"|"+AssetDatabase.GetAssetPath(r.sharedMaterial);}
 static void Correct(GameObject root,bool loader){var effect=root.GetComponentsInChildren<ExhaustSmokeEffect>(true).Single();string settings=Settings(effect.particles);var rotation=effect.transform.localRotation;effect.transform.localPosition=ExhaustSmokeAuthoring.OutletPosition(root,loader);Check(settings==Settings(effect.particles),"particle settings changed");Check(rotation==effect.transform.localRotation,"emitter direction changed");EditorUtility.SetDirty(effect.transform);}
 static void ValidateOutlet(GameObject root,bool loader){var effect=root.GetComponentInChildren<ExhaustSmokeEffect>();var body=root.GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="body");var tip=loader?new Vector3(-.38f,2.75f,-1.3f):new Vector3(-.42f,2.795f,.46f);int ring=0;using(var data=MeshUtility.AcquireReadOnlyMeshData(body.sharedMesh))using(var vertices=new NativeArray<Vector3>(data[0].vertexCount,Allocator.Temp)){data[0].GetVertices(vertices);foreach(var v in vertices)if(Mathf.Abs(v.x-tip.x)<.085f&&Mathf.Abs(v.z-tip.z)<.085f&&Mathf.Abs(v.y-tip.y)<.002f)ring++;}Check(ring>=3,"source pipe top not found in imported mesh");Check(Vector3.Distance(effect.transform.position,body.transform.TransformPoint(tip+Vector3.up*.005f))<.001f,"emitter not on pipe tip");Check(effect.particles.main.maxParticles>=Mathf.CeilToInt(9.6f*effect.particles.main.startLifetime.constantMax),"particle cap would limit doubled quantity");}
 static void Render(GameObject source,bool loader,bool close){var p=new PreviewRenderUtility();try{var copy=UnityEngine.Object.Instantiate(source);copy.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);p.AddSingleGO(copy);var effect=copy.GetComponentInChildren<ExhaustSmokeEffect>();effect.particles.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);effect.particles.useAutoRandomSeed=false;effect.particles.randomSeed=41;effect.particles.Emit(1);effect.particles.Simulate(.01f,true,false,true);var particles=new ParticleSystem.Particle[24];int count=effect.particles.GetParticles(particles);Check(count==1&&Vector3.Distance(particles[0].position,effect.transform.position)<.04f,"first puff offset from outlet");p.camera.orthographic=true;p.camera.orthographicSize=close?.55f:3.5f;p.camera.nearClipPlane=.03f;p.camera.farClipPlane=100;var center=close?effect.transform.position:Vector3.up*1.6f;var direction=loader?new Vector3(-1,.3f,-1):new Vector3(-1,.3f,1);p.camera.transform.position=center+direction.normalized*12;p.camera.transform.LookAt(center);p.camera.clearFlags=CameraClearFlags.SolidColor;p.camera.backgroundColor=new Color(.35f,.43f,.48f);p.ambientColor=Color.gray;p.lights[0].intensity=1.2f;p.lights[0].transform.rotation=p.camera.transform.rotation;p.BeginStaticPreview(new Rect(0,0,1000,800));p.Render(true);var image=p.EndStaticPreview();File.WriteAllBytes(Logs+"/"+(loader?"Loader":"Tractor")+(close?"-tip":"-full")+".png",image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}finally{p.Cleanup();}}
 [MenuItem("Snowglow/Effects/Correct exhaust tips and double smoke quantity")]
 public static void Run(){checks=0;Directory.CreateDirectory(Logs);var scene=SceneManager.GetActiveScene();Check(scene.path==SceneValidation.ScenePath&&!EditorApplication.isPlayingOrWillChangePlaymode,"open Pinefall with Play stopped");SceneValidation.Validate(scene);if(scene.isDirty)EditorSceneManager.SaveScene(scene,Logs+"/Pinefall-unsaved-before.unity",true);if(!File.Exists(Logs+"/Pinefall-before.unity"))File.Copy(scene.path,Logs+"/Pinefall-before.unity");var session=All<PrototypeSession>(scene).Single();var seed=AssetDatabase.GetAssetPath(session.Snow.seed);var seedHash=AssetDatabase.GetAssetDependencyHash(seed);var poses=All<CatalogPlacement>(scene).ToDictionary(x=>GlobalObjectId.GetGlobalObjectIdSlow(x).ToString(),x=>x.transform.localToWorldMatrix.ToString("R"));var fleet=session.Fleet.Select(m=>m.transform.localToWorldMatrix.ToString("R")).ToArray();var paths=new[]{StarterPlowAuthoring.PrefabPath,"Assets/Snowglow/Catalog/Prefabs/ImportedSnowLoader.prefab"};
 for(int i=0;i<2;i++){string backup=Logs+"/"+Path.GetFileName(paths[i]);if(!File.Exists(backup))File.Copy(paths[i],backup);var root=PrefabUtility.LoadPrefabContents(paths[i]);try{Correct(root,i==1);ValidateOutlet(root,i==1);PrefabUtility.SaveAsPrefabAsset(root,paths[i]);}finally{PrefabUtility.UnloadPrefabContents(root);}var saved=AssetDatabase.LoadAssetAtPath<GameObject>(paths[i]);ValidateOutlet(saved,i==1);Render(saved,i==1,true);Render(saved,i==1,false);}
 for(int i=0;i<session.Fleet.Length;i++){Correct(session.Fleet[i].gameObject,session.Fleet[i].definition.loader);PrefabUtility.RecordPrefabInstancePropertyModifications(session.Fleet[i].GetComponentInChildren<ExhaustSmokeEffect>().transform);ValidateOutlet(session.Fleet[i].gameObject,session.Fleet[i].definition.loader);}
 for(int t=0;t<=10;t++)for(int l=0;l<=10;l++){float throttle=t/10f,load=l/10f;float old=Mathf.Min(2.4f,.25f+1.35f*throttle+.8f*load);float actual=ExhaustSmokeEffect.CalculateEmissionRate(true,true,true,10,100,throttle,load);Check(Mathf.Abs(actual-old*4)<.00001f,"quantity not four times original");}Check(ExhaustSmokeEffect.CalculateEmissionRate(true,false,true,10,100,1,1)==0,"pause gate changed");Check(ExhaustSmokeEffect.CalculateEmissionRate(false,true,true,10,100,1,1)==0,"inactive gate changed");
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);Check(EditorSceneManager.SaveScene(scene),"save failed");scene=EditorSceneManager.OpenScene(SceneValidation.ScenePath);SceneValidation.Validate(scene);MechanicsChecks.Run();session=All<PrototypeSession>(scene).Single();Check(seed==AssetDatabase.GetAssetPath(session.Snow.seed)&&seedHash==AssetDatabase.GetAssetDependencyHash(seed),"snow changed");Check(fleet.SequenceEqual(session.Fleet.Select(m=>m.transform.localToWorldMatrix.ToString("R"))),"machinery moved");foreach(var p in All<CatalogPlacement>(scene))Check(poses[GlobalObjectId.GetGlobalObjectIdSlow(p).ToString()]==p.transform.localToWorldMatrix.ToString("R"),"scenery moved");foreach(var m in session.Fleet)ValidateOutlet(m.gameObject,m.definition.loader);
 File.WriteAllText(Logs+"/TipValidation.txt","PASS: Unity "+Application.unityVersion+" / "+EditorUserBuildSettings.activeBuildTarget+"; "+checks+" assertions. Both emitters follow source pipe tips through actual fitted body transforms, 5 mm above outlet surfaces. Imported top-ring vertices and fresh particle positions checked; four native views written. Emission four times original across 121 throttle/load combinations: idle 1/s, maximum 9.6/s. Start speed, simulation speed, velocity/drift, lifetime, size, cone, mesh/material and particle cap preserved. Prefabs saved/reloaded and Pinefall saved/reopened; scene validation/19 snow checks passed. Snow hash, fleet/catalog poses preserved; no source-model, physics or player-save changes. Live moving smoke and Android/A07 cost untested.");Debug.Log(File.ReadAllText(Logs+"/TipValidation.txt"));}
 }
}
